INSERT INTO hospital_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (38, true, '38|||אשפוז פסיכיאטרי', '38|||רשימת בתי חולים פסיכיאטריים ומחלקות פסיכיאטריות בבתי חולים כלליים. באתר.', '{"org":"משרד הבריאות","svc":"רשימת בתי חולים פסיכיאטריים ומחלקות פסיכיאטריות בבתי חולים כלליים. באתר.","region":"כל הארץ","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ministry of Health","svc":"A list of psychiatric hospitals and psychiatric departments in general hospitals. On the website.","region":"Nationwide"}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.'),
  (292, true, '292|||מחלקה פתוחה לאשפוז בטראומה מורכבת — כולל נפגעי 7 באוקטובר ובני משפחותיהם', '292|||אשפוז בטראומה מורכבת, עם פסיכיאטרים, פסיכולוגים וטיפול באומנויות. במחלקה פתוחה.', '{"svc":"אשפוז בטראומה מורכבת, עם פסיכיאטרים, פסיכולוגים וטיפול באומנויות. במחלקה פתוחה.","target":"מי שחוו את המלחמה מקרוב, ובני משפחותיהם","region":"באר יעקב, על-אזורית","meeting":"in_person","notes":"גם למי שחוו התעללות בעבר ובהתדרדרות בעקבות מצב החירום. מענה ארוך טווח. בניהול ד״ר דפנה ערמון. הוקמה אחרי 7 באוקטובר. מחלקת לצידך בכרטיס נפרד.","phoneLabel":"טלפון","phoneShowNumber":false}'::jsonb, '{"org":"Bedarki (Merhavim, Beer Yaakov)","svc":"Hospitalization for complex trauma, with psychiatrists, psychologists, and art therapy. In an open ward.","target":"People who experienced the war at close hand, and their families","region":"Beer Yaakov, supra-regional","specialty":"Complex trauma","notes":"Also for people who experienced abuse in the past and a deterioration following the state of emergency. A long-term response. Directed by Dr. Dafna Armon. Opened after 7 October. The Letzidech ward is a separate card.","phoneLabel":"Phone"}'::jsonb, '28.11.2026: דף היחידה במשרד הבריאות לא נטען. הניסוח לפי התיאור שפורסם, והטלפון שכבר בכרטיס. הניסוח אושר עם אצוות האשפוז.'),
  (293, true, '293|||מחלקה פתוחה לנשים עם פוסט־טראומה מורכבת והפרעות אכילה', '293|||אשפוז לנשים עם פוסט־טראומה מורכבת והפרעות אכילה. במחלקה פתוחה.', '{"svc":"אשפוז לנשים עם פוסט־טראומה מורכבת והפרעות אכילה. במחלקה פתוחה.","target":"נשים מגיל 18","region":"באר יעקב, כל הארץ","cost":"כללית ומאוחדת","meeting":"in_person","notes":"הקבלה אלקטיבית, אחרי ראיון. היחידה בארץ שמטפלת בטראומה מינית ובהפרעות אכילה תחת קורת גג אחת. יש גם מרפאת המשך בבאר יעקב וטיפול יום בקמפוס נס ציונה. מחלקת בדרכי בכרטיס נפרד.","phoneLabel":"מזכירות","phoneShowNumber":false,"phoneLabel2":"מרכזייה","phoneShowNumber2":false}'::jsonb, '{"org":"Letzidech (Merhavim, Beer Yaakov)","svc":"Hospitalization for women with complex PTSD and eating disorders. In an open ward.","target":"Women aged 18 and over","region":"Beer Yaakov, nationwide","cost":"Clalit and Meuhedet","specialty":"Sexual trauma, eating disorders","notes":"Admission is elective, after an interview. The only unit in the country that treats sexual trauma and eating disorders under one roof. There is also a follow-up clinic in Beer Yaakov and day treatment at the Ness Ziona campus. The Bedarki ward is a separate card.","phoneLabel":"Secretariat","phoneLabel2":"Switchboard"}'::jsonb, '28.11.2026: דף היחידה במשרד הבריאות לא נטען. הניסוח לפי התיאור שפורסם, והטלפון שכבר בכרטיס. הניסוח אושר עם אצוות האשפוז.'),
  (340, true, '340|||אשפוז ממוקד, מרפאה וטיפול יום לנפגעי ולנפגעות טראומה מינית', '340|||אשפוז ממוקד לטראומה מינית: אבחון וטיפול תרופתי, וגם פסיכותרפיה. בשהייה מלאה במחלקה, עד שבועיים.', '{"svc":"אשפוז ממוקד לטראומה מינית: אבחון וטיפול תרופתי, וגם פסיכותרפיה. בשהייה מלאה במחלקה, עד שבועיים.","target":"נשים וגברים מגיל 18, שנמצאים בטיפול בקהילה","region":"שער מנשה, כל הארץ","founded":"2012","meeting":"in_person","approaches":"פסיכותרפיה, טיפול באומנויות","notes":"הפנייה מהגורם המטפל בקהילה, ואחרי האשפוז חוזרים לטיפול בקהילה. המחלקה פתוחה ומעורבת, עם לינה נפרדת. המרפאה וטיפול היום בכרטיסים נפרדים.","phoneLabel":"טלפון","phoneShowNumber":false,"emailLabel":"אימייל","emailShowAddress":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Shaar Menashe, Sexual Trauma","svc":"Focused hospitalization for sexual trauma: assessment and medication, and also psychotherapy. A full stay on the ward, up to two weeks.","target":"Women and men aged 18 and over who are in treatment in the community","region":"Shaar Menashe, nationwide","founded":"2012","specialty":"Sexual trauma","approaches":"Psychotherapy, art therapy","notes":"Referral is from the community therapist, and after the hospitalization they return to community treatment. The ward is open and mixed, with separate sleeping areas. The clinic and the day program are separate cards.","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.'),
  (341, true, '341|||אשפוז ממוקד ל-16 יום, וטיפול יום במרכז עוגן', '341|||אשפוז ממוקד לטראומה מינית, לייצוב במשבר. בשהייה מלאה במחלקה, 16 יום.', '{"svc":"אשפוז ממוקד לטראומה מינית, לייצוב במשבר. בשהייה מלאה במחלקה, 16 יום.","target":"נשים וגברים מגיל 18, בטיפול פרטני בקהילה","region":"לב השרון","meeting":"in_person","notes":"ההפניה מהגורם המטפל בקהילה. מתקיים במחלקת נשים פתוחה או במחלקה פתוחה מעורבת. לפני הקבלה אפשר פגישת היכרות.","phone":"09-8981111","phoneLabel":"טלפון","phoneShowNumber":false,"email":"shanir@lev-hasharon.co.il","emailLabel":"אימייל","emailShowAddress":false,"webLabel":"אשפוז ממוקד","webLabel2":"המערך","phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"web":"https://www.lev-hasharon.co.il/?clinic=%D7%90%D7%A9%D7%A4%D7%95%D7%96-%D7%9E%D7%9E%D7%95%D7%A7%D7%93-%D7%9C%D7%A0%D7%A4%D7%92%D7%A2%D7%95%D7%AA-%D7%98%D7%A8%D7%90%D7%95%D7%9E%D7%94-%D7%9E%D7%99%D7%A0%D7%99%D7%AA","web2":"https://www.lev-hasharon.co.il/?ward=%D7%9E%D7%A2%D7%A8%D7%9A-%D7%9C%D7%98%D7%99%D7%A4%D7%95%D7%9C-%D7%91%D7%98%D7%A8%D7%90%D7%95%D7%9E%D7%94-%D7%9E%D7%99%D7%A0%D7%99%D7%AA"}'::jsonb, '{"org":"Lev HaSharon, Sexual Trauma","svc":"Focused hospitalization for sexual trauma, for stabilization in a crisis. A full stay on the ward, 16 days.","target":"Women and men aged 18 and over, in individual treatment in the community","region":"Lev HaSharon","specialty":"Sexual trauma","notes":"Referral is from the community therapist. It takes place on an open women ward or on an open mixed ward. A meeting to get acquainted is possible before admission.","phone":"09-8981111","phoneLabel":"Phone","emailLabel":"Email","webLabel":"Focused hospitalization","webLabel2":"The service"}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.'),
  (342, true, '342|||יחידת אשפוז לנשים אחרי פגיעה מינית', '342|||אשפוז לנשים אחרי פגיעה מינית: טיפול תרופתי, וגם טיפול תומך. בשהייה מלאה ביחידה, עד שלושה שבועות.', '{"svc":"אשפוז לנשים אחרי פגיעה מינית: טיפול תרופתי, וגם טיפול תומך. בשהייה מלאה ביחידה, עד שלושה שבועות.","target":"נשים מגיל 18, שנמצאות בטיפול","region":"תל אביב, כל הארץ","founded":"2016","meeting":"in_person","notes":"ארבע מיטות במחלקה הפתוחה. מרצון, עם מקום מגורים קבוע. לא לשימוש לרעה בחומרים, לא להפרעת אכילה שדורשת מחלקה ייעודית, ולא למצב שדורש מחלקה סגורה. הפנייה בטופס בדף היחידה."}'::jsonb, '{"org":"Magen (Ichilov)","svc":"Hospitalization for women after sexual assault: medication, and also supportive care. A full stay on the unit, up to three weeks.","target":"Women aged 18 and over who are in treatment","region":"Tel Aviv, nationwide","founded":"2016","specialty":"Sexual trauma","notes":"Four beds on the open psychiatric ward. Voluntary, with a permanent place to return to. Not for substance misuse, not for an eating disorder that needs a dedicated ward, and not for a condition that needs a closed ward. Referral is through the form on the unit page."}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.'),
  (43, true, '43|||אשפוז בית פסיכיאטרי', '43|||אשפוז בית פסיכיאטרי: אבחון וטיפול תרופתי, ובמידת הצורך גם פסיכותרפיה. בבית.', '{"svc":"אשפוז בית פסיכיאטרי: אבחון וטיפול תרופתי, ובמידת הצורך גם פסיכותרפיה. בבית.","target":"בני 18 ומעלה","region":"כל הארץ","founded":"2021","cost":"ללא עלות, בהפניה מכללית, ממאוחדת או מלאומית","specialty":"דיכאון, חרדה, פסיכוזה, PTSD, סכיזופרניה","meeting":"in_person","notes":"לרוב שישה עד שמונה שבועות. נדרש מלווה בגיר. לא לאובדנות פעילה ולא לאשפוז בכפייה. המוקד עונה בכל שעה. ההפניה מרופא המשפחה, מהפסיכיאטר, או ממיון.","phone":"1-700-508-586","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"03-7545928","phoneLabel2":"משרד","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Sharan Medical Home Care","svc":"Psychiatric home hospitalization: assessment and medication, and psychotherapy when needed. At home.","target":"People aged 18 and over","region":"Nationwide","founded":"2021","cost":"Free of charge, with a referral from Clalit, Meuhedet, or Leumit","specialty":"Depression, anxiety, psychosis, PTSD, schizophrenia","notes":"Usually six to eight weeks. An adult companion is required. Not for active suicidality and not for involuntary hospitalization. The hotline answers at all hours. The referral comes from the family doctor, the psychiatrist, or the emergency room.","phone":"1-700-508-586","phoneLabel":"Hotline","phone2":"03-7545928","phoneLabel2":"Office"}'::jsonb, '28.11.2026: העמוד מציין פריסה ארצית לכללית, למאוחדת וללאומית. ההגבלה לחמישה מחוזות של כללית לא מופיעה בו, וירדה. הניסוח אושר עם אצוות האשפוז.'),
  (45, true, '45|||הקול שבפנים – טיפול ביתי לצעירים במצבי משבר נפשי', '45|||טיפול ביתי למשפחות במשבר נפשי: טיפול רגשי, ומעקב פסיכיאטרי. בבית.', '{"svc":"טיפול ביתי למשפחות במשבר נפשי: טיפול רגשי, ומעקב פסיכיאטרי. בבית.","target":"צעירים ובגירים, ובני משפחה","region":"תל אביב, חיפה, רמת גן, גבעתיים, חולון, ראשון לציון, הרצליה, נתניה, רמת השרון, כפר סבא, פתח תקווה, רעננה, מודיעין, באר שבע, אשקלון, עמק יזרעאל, טבעון, פרדס חנה","cost":"","specialty":"דיכאון, חרדה, פסיכוזה, סכיזופרניה, פוסט־טראומה, הסתגרות","meeting":"in_person","notes":"כרגע לא מקבלים פניות חדשות. המפגשים שבועיים, ויש גם זמינות דיגיטלית.","web":"https://www.voiceover-israel.com/","phone":"03-7545928","phoneLabel":"טלפון","phoneShowNumber":false,"email":"nefesh@med-trix.com","emailLabel":"אימייל","emailShowAddress":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Sharan Medical Home Care","svc":"Home treatment for families in a mental crisis: emotional care, and psychiatric follow-up. At home.","target":"Young people and adults, and family members","region":"Tel Aviv, Haifa, Ramat Gan, Givatayim, Holon, Rishon LeZion, Herzliya, Netanya, Ramat HaSharon, Kfar Saba, Petah Tikva, Raanana, Modiin, Beer Sheva, Ashkelon, Jezreel Valley, Tivon, Pardes Hanna","specialty":"Depression, anxiety, psychosis, schizophrenia, PTSD, withdrawal","notes":"Not taking new referrals at the moment. Meetings are weekly, and there is also digital availability.","phone":"03-7545928","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, '28.11.2026: דף הבית כותב שכרגע אין קבלה של פניות חדשות. טווח הגילאים והמילה פרטי לא מופיעים בעמוד, וירדו. הניסוח אושר עם אצוות האשפוז.'),
  (48, true, '48|||אשפוז בית פסיכיאטרי', '48|||אשפוז בית פסיכיאטרי: אבחון וטיפול תרופתי, וגם ליווי רגשי. בבית.', '{"svc":"אשפוז בית פסיכיאטרי: אבחון וטיפול תרופתי, וגם ליווי רגשי. בבית.","target":"מי שיכול לשהות בבית, עם מלווה","cost":"מכבי, מאוחדת ולאומית","specialty":"חלופת אשפוז","meeting":"in_person","notes":"הצוות זמין בכל שעה. לא למי שזקוק להשגחה בכל שעה, ולא למי שמסרב לטיפול התרופתי. המשרד במחשב 3, נתניה.","phone":"*2590","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"072-2508878","phoneLabel2":"משרד","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Sabar Medical","svc":"Psychiatric home hospitalization: assessment and medication, and also emotional support. At home.","target":"A person who can stay at home, with a companion","cost":"Maccabi, Meuhedet, and Leumit","specialty":"An alternative to hospitalization","notes":"The team is available at all hours. Not for someone who needs supervision at all hours, and not for someone who refuses the medication. The office is at 3 HaMahshev, Netanya.","phone":"*2590","phoneLabel":"Hotline","phone2":"072-2508878","phoneLabel2":"Office"}'::jsonb, '28.11.2026: העמוד מפרסם את מכבי, מאוחדת ולאומית, ולא מפרסם אזור כיסוי. הניסוח אושר עם אצוות האשפוז.'),
  (53, true, '53|||חלופת אשפוז', '53|||רשימת בתים מאזנים, חלופה לאשפוז פסיכיאטרי. באתר.', '{"org":"משרד הבריאות","svc":"רשימת בתים מאזנים, חלופה לאשפוז פסיכיאטרי. באתר.","region":"כל הארץ","cost":"קופת החולים, בהשתתפות עצמית","notes":"השהות בין חודש לחודשיים. יש בתים לנוער, למבוגרים, להפרעות אכילה ולפוסט־טראומה, וגם בתים לנשים, לגברים, לחברה הערבית ולציבור החרדי. לא לכל בית יש הסדר עם כל קופה.","phone":"*5400","phoneLabel":"משרד הבריאות","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ministry of Health","svc":"A list of balancing homes, an alternative to psychiatric hospitalization. On the website.","region":"Nationwide","cost":"The health fund, with a copay","notes":"The stay is between one and two months. There are homes for youth, for adults, for eating disorders and for PTSD, and also homes for women, for men, for Arab society, and for the Haredi community. Not every home has an arrangement with every health fund.","phone":"*5400","phoneLabel":"Ministry of Health","webLabel":"List of homes","addLabel":"What a balancing home is"}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.'),
  (79, true, '79|||תוכנית טיפול ביתי ממושך למתמודדים עם מחלת נפש חמורה', '79|||טיפול ביתי ממושך למי שמתמודד עם מחלה נפשית קשה: אבחון וטיפול תרופתי, וגם ליווי. בבית.', '{"svc":"טיפול ביתי ממושך למי שמתמודד עם מחלה נפשית קשה: אבחון וטיפול תרופתי, וגם ליווי. בבית.","target":"בני 18 ומעלה עם מחלה נפשית קשה, שמתקשים להתמיד בטיפול","region":"מרכז, ירושלים","specialty":"סכיזופרניה, דיכאון, חרדה, הפרעה דו־קוטבית","meeting":"in_person","notes":"ליווי ביום-יום, איזון תרופתי, וסיוע במיצוי זכויות. הפסיכיאטר בשיחת וידאו, והליווי בבית.","phoneLabel":"טלפון","phoneShowNumber":false,"emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"Sharan Medical Home Care","svc":"Long-term home treatment for a person coping with a severe mental illness: assessment and medication, and also accompaniment. At home.","target":"People aged 18 and over with a severe mental illness, who have trouble staying in treatment","region":"Center, Jerusalem","specialty":"Schizophrenia, depression, anxiety, bipolar disorder","notes":"Accompaniment in daily life, medication balancing, and help with rights. The psychiatrist is on a video call, and the accompaniment is at home.","phone":"050-6222026","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, '28.11.2026: עמוד הפרויקט כותב שהסבב של 2023-2024 הסתיים. הכרטיס נשאר תוכנית פעילה, כפי שנמסר. הניסוח אושר עם אצוות האשפוז.'),
  (778, true, '778|||בית מאזן פרטי יוקרתי, ללא רשימת המתנה', '778|||בית מאזן פרטי: טיפול פסיכיאטרי ותרופתי, וגם טיפול רגשי. בשהייה בבית.', '{"svc":"בית מאזן פרטי: טיפול פסיכיאטרי ותרופתי, וגם טיפול רגשי. בשהייה בבית.","target":"מבוגרים מגיל 18","founded":"2019","cost":"פרטי, וגם למי שהוכר באגף השיקום","meeting":"in_person","notes":"הבית ברמת ים 77. גם למי שהוכר במשרד הביטחון, אגף השיקום. רוח ים פרובנס בכרטיס נפרד.","phoneLabel":"טלפון","phoneShowNumber":false,"phoneLabel2":"חמוטל","phoneShowNumber2":false,"emailLabel":"אימייל","emailShowAddress":false,"whatsappLabel":"וואטסאפ"}'::jsonb, '{"org":"Ruah Yam","svc":"A private balancing home: psychiatric and medication treatment, and also emotional care. A stay at the home.","target":"Adults aged 18 and over","region":"Herzliya","founded":"2019","cost":"Private, and also for a person recognized by the Rehabilitation Department","notes":"The home is at 77 Ramat Yam. Also for a person recognized by the Ministry of Defense, Rehabilitation Department. Ruah Yam Provence is a separate card.","phoneLabel":"Phone","phoneLabel2":"Hamutal","emailLabel":"Email","whatsappLabel":"WhatsApp"}'::jsonb, '28.11.2026: המשפט ללא רשימת המתנה לא מופיע בעמוד, וירד. הניסוח אושר עם אצוות האשפוז.'),
  (779, true, '779|||בית מאזן', '779|||בית מאזן: טיפול פסיכיאטרי, וגם טיפול פסיכולוגי. בשהייה בבית.', '{"svc":"בית מאזן: טיפול פסיכיאטרי, וגם טיפול פסיכולוגי. בשהייה בבית.","cost":"פרטי","specialty":"תחלואה כפולה, דיכאון, פוסט־טראומה","meeting":"in_person","notes":"הבית בנחשון 2. עובדים עם האגף לנפגעי פעולות איבה. פגישת ייעוץ ראשונה בלי התחייבות. לא כל תוכנית כוללת טיפול תרופתי. רוח ים ברמת ים בכרטיס נפרד.","phoneLabel":"טלפון","phoneShowNumber":false,"emailLabel":"אימייל","emailShowAddress":false,"whatsapp":"","whatsappLabel":""}'::jsonb, '{"org":"Ruah Yam Provence","svc":"A balancing home: psychiatric treatment, and also psychological treatment. A stay at the home.","target":"People in an acute mental crisis","region":"Herzliya","cost":"Private","specialty":"Dual diagnosis, depression, PTSD","notes":"The home is at 2 Nahshon. They work with the Hostilities Victims Department. A first consultation is without commitment. Not every program includes medication. Ruah Yam at Ramat Yam is a separate card.","phone":"055-6698519","phoneLabel":"Phone","emailLabel":"Email"}'::jsonb, '28.11.2026: מספר הוואטסאפ לא מופיע בעמוד, וירד. הניסוח אושר עם אצוות האשפוז.'),
  (782, true, '782|||בית מאזן לנשים עם פוסט־טראומה מורכבת והפרעת אכילה', '782|||בית מאזן לנשים: מעקב פסיכיאטרי, וגם פסיכותרפיה. בשהייה בבית.', '{"svc":"בית מאזן לנשים: מעקב פסיכיאטרי, וגם פסיכותרפיה. בשהייה בבית.","target":"נשים מגיל 18","cost":"פרטי, עם הסדר מול מאוחדת","specialty":"הפרעות אכילה, פוסט־טראומה","approaches":"CBT, DBT, טיפול דינמי, EMDR","meeting":"in_person","notes":"חלופת אשפוז ברישיון משרד הבריאות. שהות של שלושה חודשים, ואחר כך אפשרות לטיפול יום. הקבלה בהסכמה, מ-BMI 16, בלי הזנה בזונדה. לא לסכנה רפואית, להתמכרות פעילה, או לסכנה מיידית. הבית ברחוב צה״ל 2א."}'::jsonb, '{"org":"Alma","svc":"A balancing home for women: psychiatric follow-up, and also psychotherapy. A stay at the home.","target":"Women aged 18 and over","region":"Tzahala, Tel Aviv","cost":"Private, with an arrangement with Meuhedet","specialty":"Eating disorders, PTSD","approaches":"CBT, DBT, dynamic therapy, EMDR","languages":"Hebrew","notes":"A hospitalization alternative licensed by the Ministry of Health. A stay of three months, and then the option of day treatment. Admission is by consent, from a BMI of 16, without tube feeding. Not for a medical danger, active addiction, or immediate danger. The home is at 2A Tzahal Street.","phoneLabel":"Phone","emailLabel":"Email","webLabel2":"Intake","whatsappLabel":"WhatsApp"}'::jsonb, '28.11.2026: נבדק מול אתר הארגון. הניסוח אושר עם אצוות האשפוז.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM hospital_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN hospital_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM hospital_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN hospital_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

COMMIT;
